INSERT INTO `v1_f041a6a388116cf1e97b8560f62ecc248df4295ba6c2d00e2234484d5be99a9a` VALUES (10, 115711, 1, 11, 0.5, 0, "ここメルクリゾートではプールサイドで\nたい焼きを売る怪人の噂がある。", 0, 19230017, 923, 0);
