INSERT INTO `v1_f041a6a388116cf1e97b8560f62ecc248df4295ba6c2d00e2234484d5be99a9a` VALUES (7, 122511, 1, 11, 1, 0, "ずいぶんと色々なものが流れているね。\nここがプールでないなら、\n魚が潜んでいそうだけど…", 0, 19430025, 943, 0);
INSERT INTO `v1_f041a6a388116cf1e97b8560f62ecc248df4295ba6c2d00e2234484d5be99a9a` VALUES ("", 0, "", 91, "", "", "", "", 19430026, 943, "");
