INSERT INTO `v1_f041a6a388116cf1e97b8560f62ecc248df4295ba6c2d00e2234484d5be99a9a` VALUES (10, 107911, 1, 11, 1, 0, "こんなに人がいっぱいいる商機、\n見逃すわけにはいかないにゃ！", 0, 19440038, 944, 0);
