INSERT INTO `v1_f041a6a388116cf1e97b8560f62ecc248df4295ba6c2d00e2234484d5be99a9a` VALUES (10, 110411, 1, 11, 1, 0, "どうしたんだ、ユイ？\nあいつのために\nわざわざ弁当作ってきたんだろ？\nとっとと誘えばいいじゃないか。", 0, 19450021, 945, 0);
INSERT INTO `v1_f041a6a388116cf1e97b8560f62ecc248df4295ba6c2d00e2234484d5be99a9a` VALUES ("", 0, "", 91, "", "", "", "", 19450022, 945, "");
